import random

def simulate_coin_flips(n):
    heads = 0
    tails = 0
    for _ in range(n):
        x = random.randint(1, 100)
        if x > 50:
            heads += 1
        else:
            tails += 1
    return heads, tails

def count_odd_even(n):
    odd_count = 0
    even_count = 0
    for i in range(1, n + 1):
        if i % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return odd_count, even_count

def fibonacci(n):
    if n >= 1:
        print(0)
    if n >= 2:
        print(1)

    # Use variables to track the last two numbers
    if n >= 3:
        prev_prev = 0  # F(0)
