def classify_multiples(n):
    for num in range(1, n + 1):
        if num % 3 == 0 and num % 5 == 0:
            print('Mult35')
        elif num % 3 == 0:
            print('Mult3')
        elif num % 5 == 0:
            print('Mult5')
        else:
            print(num)

