def primes_less_than(n):
    for num in range(2, n):
        is_prime = True
        for d in range(2, num // 2 + 1):
            if num % d == 0:
                is_prime = False
                break
        if is_prime:
            print(num)

def pythagorean_pairs(n):
    for x in range(1, n):
        for y in range(1, n):
            if x**2 + y**2 == n**2:
                print(x, y)
